"""
reasons.py
-----------
Groups the free-text reasons experts write, so the system can count how many
fake verdicts share "the same reason".

Two reasons count as the same when most of the key words of the shorter one
also appear in the other, after dropping filler words and simple word endings:
    "skin looks too smooth"  ~  "smooth, waxy skin"      (smooth, skin)
    "AI generated face"      ~  "face generated by AI"   (ai, generat, face)
    "smooth skin"            !~ "smooth background"
"""

import re
from collections import Counter

STOP = {
    'a', 'an', 'the', 'and', 'or', 'but', 'of', 'to', 'in', 'on', 'at', 'by', 'for', 'with', 'from',
    'is', 'are', 'was', 'were', 'be', 'been', 'it', 'its', 'this', 'that', 'these', 'those', 'there',
    'image', 'photo', 'picture', 'pic', 'file', 'looks', 'look', 'looking', 'seems', 'seem', 'appears',
    'very', 'too', 'quite', 'really', 'bit', 'some', 'all', 'has', 'have', 'had', 'not', 'no', 'so',
    'as', 'like', 'also', 'i', 'we', 'think', 'clearly', 'obviously', 'probably', 'fake', 'real',
    'because', 'due', 'which', 'who', 'my', 'our', 'can', 'could', 'see', 'seen', 'shows', 'show',
}
SUFFIXES = ('ations', 'ation', 'ings', 'ing', 'edly', 'ness', 'ies', 'ed', 'es', 'ly', 's')
SAME_REASON = 0.6        # share of the shorter reason's key words that must match


def stem(word):
    for suffix in SUFFIXES:
        if word.endswith(suffix) and len(word) - len(suffix) >= 3:
            return word[:-len(suffix)]
    return word


def keywords(text):
    words = re.findall(r'[a-z0-9]+', (text or '').lower())
    return {stem(w) for w in words if w not in STOP and (len(w) > 1 or w.isdigit())}


def is_valid(text):
    """A reason needs at least one meaningful word to be counted."""
    return bool(keywords(text))


def _core(group):
    """Key words that appear in at least half of the group's reasons."""
    size = len(group['ids'])
    return {w for w, c in group['words'].items() if c >= max(1, size / 2)}


def group_reasons(items):
    """
    items: [(scan_id, reason_text)]
    Returns groups, largest first: [{'label', 'ids', 'examples', 'words'}].
    """
    groups = []
    for scan_id, text in items:
        kw = keywords(text)
        if not kw:
            continue
        best, best_sim = None, 0.0
        for g in groups:
            core = _core(g)
            if not core:
                continue
            shared = len(kw & core)
            if shared < min(2, len(kw), len(core)):
                continue
            sim = shared / min(len(kw), len(core))
            if sim > best_sim:
                best, best_sim = g, sim
        if best is not None and best_sim >= SAME_REASON:
            best['ids'].append(scan_id)
            best['words'].update(kw)
            if len(best['examples']) < 3:
                best['examples'].append(text.strip()[:120])
        else:
            groups.append({'ids': [scan_id], 'words': Counter(kw), 'examples': [text.strip()[:120]]})

    for g in groups:
        g['label'] = ' '.join(w for w, _ in g['words'].most_common(3))
    groups.sort(key=lambda g: len(g['ids']), reverse=True)
    return groups
